// Single scheduler for the whole pipeline.
//
// Nine separate workflows each carried their own cron. That made the daily order
// implicit, spread retry behaviour across graphs, and meant a schedule change needed
// edits in several places. Here one tick decides what is due, and n8n runs the emitted
// items through the HTTP node in order, so the morning sequence is explicit.
//
// All business logic lives behind the Social API; this node only decides *when*.

const now = new Date();
const parts = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/Lisbon', hour12: false,
  weekday: 'short', day: '2-digit', hour: '2-digit', minute: '2-digit',
}).formatToParts(now).reduce((acc, p) => (acc[p.type] = p.value, acc), {});

const hour = Number(parts.hour);
const minute = Number(parts.minute);
const day = Number(parts.day);
const weekday = parts.weekday;
const minutes = hour * 60 + minute;

const due = [];
const add = (job, path, body, timeout) => due.push({ json: { job, path, body: body ?? {}, timeout: timeout ?? 120000 } });

// --- 07:45 rolling window ------------------------------------------------------
// Rebuild the 90-day window from the brief bank before planning reads it, so the
// window can never age out from under the current date.
if (hour === 7 && minute === 45) add('planning.rebuild', '/v1/planning/rebuild', {}, 180000);
// Keep the local corpus in step with the bank: evidence research needs each brief's
// canonical page present, so a newly added brief is otherwise held for lack of a source.
if (hour === 7 && minute === 50) add('corpus.ingest-briefs', '/v1/corpus/ingest-briefs', {}, 600000);
// The rebuild at 07:45 writes a new reserve, and replace-held at 08:00 can only use a
// card whose source has been fetched and recorded. Verifying in between is what makes
// a freshly built reserve usable on the same morning rather than inert until someone
// notices the held slots.
if (hour === 7 && minute === 55) add('reserve.verify', '/v1/reserve/verify', {}, 900000);

// --- 08:00 daily planning, in order -----------------------------------------
// These must run as a sequence: sync occasions, select the day, build evidence,
// then resolve holds and the flexible news slot.
if (hour === 8 && minute === 0) {
  add('planning.sync', '/v1/planning/sync', {}, 180000);
  add('planning.daily', '/v1/planning/daily', {}, 300000);
  add('evidence.research', '/v1/evidence/research', {}, 300000);
  add('reserve.replace-held', '/v1/reserve/replace-held', {}, 180000);
  add('news.decide-flex-slot', '/v1/news/decide-flex-slot', {}, 180000);
}

// --- generation and recovery -------------------------------------------------
// Every 5 minutes across the working day. The API returns a no-op when a run is
// already in flight, so overlap is not an error.
if (hour >= 8 && hour <= 20 && minute % 5 === 2) {
  // One concept per run meant a rejected draft cost five minutes of doing nothing before
  // the next was tried, and a cap of 18 ended the day with slots still empty. Each run
  // now works through concepts until the day holds five, and keeps going across runs
  // until it does. Forty attempts is the runaway guard: at the observed pass rate five
  // posts needs roughly fifteen, and what actually limits us is tokens, which the gate
  // enforces on its own. When the planned concepts are used up the reserve is drawn on,
  // which is what it was built for.
  add('generation.recover-day', '/v1/generation/recover-day',
    { target: 5, maxRounds: 2, maxConcepts: 2, dailyAttemptBudget: 40 }, 540000);
}

// --- review delivery safety net ----------------------------------------------
// Recovery sends new drafts to Discord itself; this only catches stragglers.
// Generation hands a finished draft to review itself, so this is the catch-up pass for
// one that did not make it — a failed handoff, or a draft written by hand on the board.
// Confined to the 08:00 hour it meant anything missed before nine waited until the next
// morning to be offered for approval, which reads as an empty review queue all day.
if (hour >= 8 && hour <= 20 && minute % 15 === 10) {
  add('review.request-pending', '/v1/review/request-pending', {}, 180000);
}

// --- publishing loop ----------------------------------------------------------
// Every 2 minutes: advance approved work, hand at most one post to Buffer, then
// reconcile provider state. Buffer pacing is enforced inside the API.
if (minutes % 2 === 0) {
  add('automation.advance', '/v1/automation/advance', {}, 120000);
  // Handoff stays responsive; confirmation need not be. The monitor already refuses
  // to re-check a job more than once every ten minutes, so asking every two spent 720
  // runs a day doing the work of 144.
  if (minute % 3 === 0) add('publish.process', '/v1/publish-jobs/process', {}, 120000);
  if (minute % 10 === 4) add('publish.monitor', '/v1/publish-jobs/monitor', {}, 120000);
}

// --- discovery and official monitoring ----------------------------------------
// News has to reach a post while it is still news. On a three-hourly discovery
// followed by a three-hourly dispatch a story could be six hours old before anything
// was written about it, which is not a news slot in any useful sense.
//
// The three stages now run on a fifteen-minute pipeline offset so each hands work to
// the next within the same quarter hour: collect at :00, triage the new items at :05,
// dispatch what cleared evidence at :10. Worst-case latency drops from about six hours
// to about twenty minutes. All three are cheap -- RSS reads and local Chromium, no paid
// API -- and generation volume is unchanged because the flex slot is still one a day
// and Buffer pacing is enforced inside the API.
// Reading every fifteen minutes meant roughly 570 feed fetches, up to 1,150 article
// fetches and 240 notice-board reads a day against AT, AIMA and Seguranca Social:
// thousands of requests to find the handful of notices they publish in a week. A
// notice is no likelier to be found by asking sixteen times an hour, and that volume
// is how a scraper gets blocked. Four-hourly still catches a change on the day it is
// published, at a twentieth of the traffic.
const NEWS_HOURS = [1, 5, 9, 13, 17, 21];
const newsDue = NEWS_HOURS.includes(hour);
if (newsDue && minute === 0) add('discovery.rss', '/v1/discovery/rss', {}, 180000);
if (newsDue && minute === 5) add('verification.triage', '/v1/verification/triage', {}, 180000);
if (newsDue && minute === 10) add('news.dispatch-recent', '/v1/news/dispatch-recent', {}, 300000);

// The institutions' own notice boards, read half-hourly. This is where an administrative
// change is announced first and in full, on an official domain, so a notice found here
// is evidence in its own right rather than a story needing corroboration.
if ((hour === 7 || hour === 19) && minute === 20) add('discovery.official-announcements', '/v1/discovery/official-announcements', {}, 300000);

// Official pages are heavy to fetch and change slowly; hourly is plenty and keeps the
// government sites from seeing a fifteen-minute crawl.
if (hour % 6 === 3 && minute === 45) add('official.monitor', '/v1/official-sources/monitor', {}, 300000);

// --- operations ---------------------------------------------------------------
if (minute % 15 === 0) add('alerts.check', '/v1/alerts/check', {}, 120000);
if (hour === 9 && minute === 0) add('reports.daily', '/v1/reports/daily', {}, 180000);
if (weekday === 'Mon' && hour === 7 && minute === 0) add('maintenance.weekly', '/v1/maintenance/weekly', {}, 300000);
if (day === 1 && hour === 7 && minute === 0) add('maintenance.monthly', '/v1/maintenance/monthly', {}, 300000);

return due;

// The HTTP node is set to neverError, and to continue on error, so that one failing job
// cannot abort the remaining due jobs in the same tick — neverError alone only covers
// HTTP statuses, and a dropped connection throws past it. Real failures are re-raised here, after every
// job has had its turn, and expected no-ops are allowed through quietly.
//
// A 409 from generation means a recovery run is already in flight for the date. That is
// the overlap guard doing its job, not a fault: booking it as a failed execution is what
// made WF-04 contribute a steady stream of false errors to the n8n failure rate.
const results = $input.all().map(item => {
  const status = Number(item.json.statusCode ?? 0);
  const job = item.json.job ?? 'unknown';
  // A transport failure arrives with an error and no status at all, because the request
  // never got far enough to have one. It still has to be reported: counting it as status
  // 0 would let a connection reset pass for a clean run.
  const transport = !status && (item.json.error ?? item.error);
  return { job, status, body: item.json.body, transport: transport ? String(transport.message ?? transport) : null };
});

const benign = results.filter(r => r.status === 409 || r.status === 204);
const failed = results.filter(r => r.transport || (r.status && (r.status < 200 || r.status >= 300) && r.status !== 409 && r.status !== 204));
const ok = results.filter(r => r.status >= 200 && r.status < 300);

if (failed.length) {
  const detail = failed.map(r => `${r.job} -> ${r.transport ? `transport: ${r.transport}` : `${r.status} ${JSON.stringify(r.body).slice(0, 200)}`}`).join(' | ');
  throw new Error(`${failed.length} job(s) failed: ${detail}`);
}

return [{ json: { ran: results.length, ok: ok.length, skipped: benign.length, jobs: results.map(r => `${r.job}:${r.status}`) } }];
